package rentivo_backend.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="contact_accesses",uniqueConstraints=@UniqueConstraint(name="uk_contact_access_user_listing",columnNames={"user_id","listing_id"}))
public class ContactAccess { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="listing_id") private Listing listing; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="subscription_id") private UserSubscription subscription; @Column(nullable=false) private LocalDateTime unlockedAt=LocalDateTime.now(); public Long getId(){return id;} public User getUser(){return user;} public Listing getListing(){return listing;} public UserSubscription getSubscription(){return subscription;} public LocalDateTime getUnlockedAt(){return unlockedAt;} public void setId(Long v){id=v;} public void setUser(User v){user=v;} public void setListing(Listing v){listing=v;} public void setSubscription(UserSubscription v){subscription=v;} public void setUnlockedAt(LocalDateTime v){unlockedAt=v;} }
